mapper.select:
SELECT * FROM ( SELECT user_id, email, name, nickname, age, role, grade, gender, disease, disability, medication, profile_img, created_at, updated_at, deleted_at, total_count, total_distance, ROW_NUMBER() OVER (ORDER BY created_at DESC) as rn FROM users WHERE deleted_at IS NULL
AND (nickname LIKE '%' || #{search} || '%' OR name LIKE '%' || #{search} || '%')
) WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{pageSize}
